fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut max_len = 1;
    let mut curr_len = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            curr_len += 1;
        } else {
            max_len = max_len.max(curr_len);
            curr_len = 1;
        }
    }

    max_len.max(curr_len)
}

